import json, re

with open('/root/trace_distill_repair/pipeline_output/phase3_v2_checkpoint.json') as f:
    data = json.load(f)

all_results = []
for key, results in data.items():
    for r in results:
        all_results.append(r)

failures = [r for r in all_results if not r.get('diff_apply_success', True)]

print("=== FAILURE CLASSIFICATION ===\n")

for r in failures:
    inst = r.get('instance_id', '?')
    cond = r.get('condition', '?')
    stderr = r.get('test_stderr_snippet', '')
    raw_diff = r.get('raw_diff', '')

    print(f"--- {inst} | {cond} ---")

    # Parse hunk headers
    hunks = re.findall(r'@@ -(\d+),(\d+) \+(\d+),(\d+) @@', raw_diff)

    # Count actual lines
    lines = raw_diff.split('\n')

    # Find issues
    issues = []

    # 1. Check hunk line counts
    for hunk_match in hunks:
        old_start, old_count, new_start, new_count = [int(x) for x in hunk_match]

        # Find lines belonging to this hunk (after @@ line, before next @@ or end)
        hunk_pattern = f'@@ -{old_start},{old_count} +{new_start},{new_count} @@'
        hunk_idx = raw_diff.find(hunk_pattern)
        if hunk_idx == -1:
            continue

        after_hunk = raw_diff[hunk_idx + len(hunk_pattern):]
        # Find next hunk or end
        next_hunk = re.search(r'\n@@ ', after_hunk)
        if next_hunk:
            hunk_body = after_hunk[:next_hunk.start()]
        else:
            hunk_body = after_hunk

        body_lines = hunk_body.split('\n')
        # Skip first element (rest of @@ line)
        body_lines = body_lines[1:]
        # Remove trailing empty
        while body_lines and body_lines[-1] == '':
            body_lines.pop()

        actual_old = 0  # context + removed
        actual_new = 0  # context + added
        empty_no_space = 0

        for bl in body_lines:
            if bl.startswith('-'):
                actual_old += 1
            elif bl.startswith('+'):
                actual_new += 1
            elif bl.startswith(' ') or bl == '':
                actual_old += 1
                actual_new += 1
                if bl == '':
                    empty_no_space += 1
            else:
                actual_old += 1
                actual_new += 1

        if actual_old != old_count:
            issues.append(f"HUNK_COUNT_MISMATCH: old expected={old_count} actual={actual_old}")
        if actual_new != new_count:
            issues.append(f"HUNK_COUNT_MISMATCH: new expected={new_count} actual={actual_new}")
        if empty_no_space > 0:
            issues.append(f"EMPTY_CONTEXT_LINES_NO_SPACE_PREFIX: {empty_no_space}")

    # 2. Check for multiple hunks
    num_hunks = len(hunks)
    if num_hunks > 1:
        issues.append(f"MULTI_HUNK: {num_hunks} hunks")

    # 3. Check patch error type
    if 'malformed patch' in stderr:
        line_num = re.search(r'malformed patch at line (\d+)', stderr)
        if line_num:
            issues.append(f"MALFORMED_AT_LINE: {line_num.group(1)}")
    elif 'unexpected end of file' in stderr:
        issues.append("UNEXPECTED_EOF")
    elif 'FAILED' in stderr:
        issues.append("HUNK_FAILED")
    elif stderr.strip() == '':
        issues.append("NO_STDERR (patch silently failed or diff_apply logic issue)")

    # 4. Check if diff ends with trailing newline
    if not raw_diff.endswith('\n'):
        issues.append("NO_TRAILING_NEWLINE")

    # Classify
    if not issues:
        category = "UNKNOWN"
    elif any('HUNK_COUNT_MISMATCH' in i for i in issues):
        category = "C: HUNK LINE COUNT MISMATCH"
    elif any('EMPTY_CONTEXT_LINES' in i for i in issues):
        category = "B: EMPTY CONTEXT LINES (missing space prefix)"
    elif any('UNEXPECTED_EOF' in i for i in issues):
        category = "B: INCOMPLETE DIFF (unexpected EOF)"
    elif any('NO_STDERR' in i for i in issues):
        category = "D: PATCH COMMAND ISSUE"
    else:
        category = "OTHER"

    print(f"  Category: {category}")
    print(f"  Issues: {issues}")
    print(f"  Hunks: {hunks}")
    print(f"  Stderr: {stderr.strip()[:100]}")
    print()

# Summary
print("\n=== CATEGORY SUMMARY ===")
categories = {}
for r in failures:
    inst = r.get('instance_id', '?')
    cond = r.get('condition', '?')
    raw_diff = r.get('raw_diff', '')
    stderr = r.get('test_stderr_snippet', '')

    hunks = re.findall(r'@@ -(\d+),(\d+) \+(\d+),(\d+) @@', raw_diff)

    has_mismatch = False
    for hunk_match in hunks:
        old_start, old_count, new_start, new_count = [int(x) for x in hunk_match]
        hunk_pattern = f'@@ -{old_start},{old_count} +{new_start},{new_count} @@'
        hunk_idx = raw_diff.find(hunk_pattern)
        if hunk_idx == -1:
            continue
        after_hunk = raw_diff[hunk_idx + len(hunk_pattern):]
        next_hunk = re.search(r'\n@@ ', after_hunk)
        if next_hunk:
            hunk_body = after_hunk[:next_hunk.start()]
        else:
            hunk_body = after_hunk
        body_lines = hunk_body.split('\n')[1:]
        while body_lines and body_lines[-1] == '':
            body_lines.pop()
        actual_old = sum(1 for bl in body_lines if bl.startswith('-') or bl.startswith(' ') or (bl == '' and not bl.startswith('+')) or (not bl.startswith('+') and not bl.startswith('-') and bl != ''))
        actual_new = sum(1 for bl in body_lines if bl.startswith('+') or bl.startswith(' ') or (bl == '' and not bl.startswith('-')) or (not bl.startswith('+') and not bl.startswith('-') and bl != ''))
        if actual_old != old_count or actual_new != new_count:
            has_mismatch = True

    if has_mismatch:
        cat = "C: hunk count mismatch"
    elif 'unexpected end' in stderr:
        cat = "B: unexpected EOF"
    elif stderr.strip() == '':
        cat = "D: silent fail"
    elif 'malformed' in stderr:
        cat = "B: malformed (likely count related)"
    else:
        cat = "E: other"

    categories[cat] = categories.get(cat, 0) + 1

for cat, count in sorted(categories.items()):
    print(f"  {cat}: {count}")

